// Twilio webhook authenticity: HMAC-SHA1 over the public URL plus the
// alphabetically sorted POST parameters, keyed with the auth token.
function twilioSignatureValid(params, headers, path) {
  const authToken = $env.TWILIO_AUTH_TOKEN || '';
  const url = ($env.TWILIO_WEBHOOK_BASE_URL || '') + '/webhook/' + path;
  const sorted = Object.keys(params).sort().map((k) => k + params[k]).join('');
  const provided = headers['x-twilio-signature'] || '';
  if (!authToken || !provided) return false;
  const expected = crypto.createHmac('sha1', authToken).update(url + sorted, 'utf8').digest('base64');
  const a = Buffer.from(expected);
  const b = Buffer.from(provided);
  return a.length === b.length && crypto.timingSafeEqual(a, b);
}
const crypto = require('crypto');
const item = $input.all()[0];
const params = item.json.body || {};
const headers = item.json.headers || {};

if (!twilioSignatureValid(params, headers, 'twilio-voice')) {
  return [{ json: { reject: true, status: 403, message: 'invalid signature' } }];
}
const callSid = params.CallSid;
if (!callSid) {
  return [{ json: { reject: true, status: 422, message: 'missing CallSid' } }];
}

const status = params.CallStatus || '';
let eventType = 'call_status';
let suffix = 'status:' + (status || 'unknown');
let content;
if (params.TranscriptionSid) {
  eventType = 'voicemail_transcription';
  suffix = 'transcription:' + params.TranscriptionSid;
  content = 'Voicemail transcription: ' + (params.TranscriptionText || '(unavailable)');
} else if (params.RecordingSid) {
  eventType = 'voicemail';
  suffix = 'recording:' + params.RecordingSid;
  // A reference only — recordings are not downloaded or stored.
  content = 'Voicemail recorded (' + (params.RecordingDuration || '?') + 's). Recording reference: ' + params.RecordingSid;
} else if (['no-answer', 'busy', 'failed', 'canceled'].includes(status)) {
  eventType = 'missed_call';
  content = 'Missed call (' + status + ') from ' + (params.From || 'unknown number');
} else if (status === 'completed') {
  eventType = 'call_completed';
  content = 'Call completed. Duration: ' + (params.CallDuration || '?') + 's';
} else {
  content = 'Call event: ' + (status || 'unknown');
}

return [{
  json: {
    reject: false,
    idempotency_key: 'twilio:call:' + callSid + ':' + suffix,
    event: {
      channel: 'phone_call',
      provider: 'twilio',
      external_event_id: callSid + ':' + suffix,
      event_type: eventType,
      sender_phone: params.From || null,
      content,
      received_at: new Date().toISOString(),
      metadata: {
        to: params.To || null,
        call_status: status || null,
        duration_seconds: params.CallDuration || null,
        recording_sid: params.RecordingSid || null,
        direction: params.Direction || null,
      },
    },
  },
}];
